import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Beyond the Last Frame: Process-aware Evaluation for Generative Video Reasoning","description":"","frontmatter":{"title":"Beyond the Last Frame: Process-aware Evaluation for Generative Video Reasoning","arxiv":"2512.24952","date":"2025-12-31","authors":"Yifan Li, Yukai Gu, Yingqian Min, Zikang Liu, Yifan Du, Kun Zhou, Min Yang, Wayne Xin Zhao, Minghui Qiu","categories":"cs.CV","topics":"生成式视频推理, 过程级评测, outcome hacking","outline":[2,2]},"headers":[],"relativePath":"papers/2512.24952.md","filePath":"papers/2512.24952.md","lastUpdated":null}'),e={name:"papers/2512.24952.md"};function l(r,s,m,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="beyond-the-last-frame-process-aware-evaluation-for-generative-video-reasoning" tabindex="-1">Beyond the Last Frame: Process-aware Evaluation for Generative Video Reasoning <a class="header-anchor" href="#beyond-the-last-frame-process-aware-evaluation-for-generative-video-reasoning" aria-label="Permalink to &quot;Beyond the Last Frame: Process-aware Evaluation for Generative Video Reasoning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.24952" target="_blank" rel="noreferrer">2512.24952</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-31</td></tr><tr><td><strong>作者</strong></td><td>Yifan Li, Yukai Gu, Yingqian Min, Zikang Liu, Yifan Du, Kun Zhou, Min Yang, Wayne Xin Zhao, Minghui Qiu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用「至少一帧达成目标 且 所有采样帧都不违反隐式约束」这条合取判据取代只看末帧的评分，把视频模型「结论对但过程错」的 outcome hacking 单独测出来。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型最近被观察到一种新能力：用连续帧把一个问题的求解过程「画」出来——走迷宫时画出路径，解数学题时逐行写推导，转动方块时保持结构。这被称为 Chain-of-Frames（CoF）推理，是把视频模型当通用视觉推理器的核心论据。</p><p>问题出在怎么评。现有 GVR benchmark 普遍取<strong>末帧</strong>或与答案<strong>最匹配的那一帧</strong>来打分。视频是一个过程，这种取法只验证结论、不验证过程。论文给这个漏洞起了个名字：<strong>outcome-hacking</strong>——模型通过一条错误的路径抵达了正确的终点，而单帧指标把它判成成功。</p><p>这不是吹毛求疵。如果 CoF 的价值在于「过程本身就是推理」，那么过程错了就等于推理错了，只是碰巧蒙对了答案。用单帧指标衡量，会系统性地高估模型的推理能力，进而误导整个方向的研究优先级。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>这个领域刚起步，但已经有一批 benchmark。「Video models are zero-shot learners and reasoners」提出了 CoF 概念，「Thinking with Video」把视频生成当作多模态推理范式，MME-CoF 做了零样本推理能力的实证研究，TiViBench、MIRA、Gen-ViRe、V-ReasonBench 各自从不同维度构建了评测集。也有工作尝试用 prompt 优化和在正确视频上做监督微调来提升推理表现。</p><p>它们共同的缺陷不在覆盖面而在<strong>评分策略</strong>。论文指出，主流做法采样末帧或最佳匹配帧，这等价于把视频压缩成一张图再评。为什么之前没人做过程评测？<strong>可以推断</strong>有两个原因：一是过程约束往往是<strong>隐式</strong>的（迷宫题不会写「不许穿墙」，因为这是常识），需要额外标注才能变成可判据；二是逐帧判断需要一个足够强的多模态 judge，而这个条件到 GPT-5 一代才勉强满足。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是把怀疑坐实。作者从已有 GVR benchmark 里挑了 50 个<strong>过程关键</strong>的例子（数学题、轨迹跟踪这类，过程错了答案就没意义），对 Veo 3.1 和 Sora 2 各采一条视频，同时用两种口径评：只看末帧的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">last</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 和看整段的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">process</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>。结果 Veo 3.1 是 66.0 对 30.0，Sora 2 是 70.0 对 24.0，hacking rate 分别 36% 和 46%。近一半的「成功」是假的。</p><p>第二步是把「过程正确」形式化。这里的关键洞察是，一个 GVR 任务的 prompt 其实包含两部分：<strong>显式目标</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>（「解开这个迷宫」）和<strong>隐式约束</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>（「不许穿墙」）。目标是存在性的——只要有一帧达成就算达成；约束是全称性的——每一帧都不能违反。这两个量词天然不同，合并成一个判据就是两者的合取。</p><p>第三步是让 judge 可靠。原始 prompt 直接问 VLM 「这段视频对不对」，与人类专家的一致率只有约 60%。作者把评判上下文分成三层——系统提示定义评判范式与输出格式、领域介绍说明该领域的评判重点、任务约束给出实例级细则——一致率提到 90% 以上。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>任务目标是存在量词，过程约束是全称量词。只看末帧等于只验证了存在量词，把全称量词整个丢掉——而推理的正确性恰恰住在全称量词里。把两个量词都写进判据，模型「蒙对答案」的路就被堵死了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>VIPER 的数据结构</strong>：每个样本是四元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">}</span></span></span></span>——初始图像、任务 prompt、过程约束、真值参考。任务 prompt 本身又拆成三块：图像描述（提供上下文与规则）、任务定义（「一条红线从起点缓缓走到终点」）、风格约束（「静态相机」「不许推拉」）。过程约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 不写进 prompt，只给 judge 用。参考 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 视任务而定：有真值视频就采真值帧，否则给一张已解状态的图；符号推理任务的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 是文字推导步骤加最终答案。</p><p><strong>任务设计</strong>：16 个任务、6 个领域、共 309 条。Temporal（Object Moving 25、World Memory 18）；Structural（Chess 20、Maze 20、Sudoku 20、Tic-Tac-Toe 10）；Symbolic（Knowledge 20、Math 20、Multimodal 20）；Spatial（Block Rotate 25、Dice Rolling 20、Image Restore 15）；Physics（Experiment 18、Game 14）；Planning（Navigation 25、Object Manipulation 19）。</p><p>作者对「什么算合法的 GVR 任务」下了定义：要么<strong>可分解</strong>（多步逻辑过程，中间帧是必要里程碑，如迷宫寻路），要么<strong>动态</strong>（过程本身就是结果，如预测碰撞）。分割、超分这类静态图像处理任务被排除在外，因为它们不需要有意义的时间演化。</p><p><strong>评测流程</strong>，以迷宫为例：输入一张 2D 迷宫图和一段 prompt（「一条实心红线从绿色方块平滑地穿过迷宫结构到达红色方块，不与墙相交，静态相机」），模型生成视频；按采样率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 均匀抽帧；GPT-5 作为 judge，按三层 rubric 先在 <code>&lt;think&gt;</code> 里分析过程一致性与目标一致性，再在 <code>&lt;answer&gt;</code> 里给出 PC、OC、POC 的判定。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>GVR 任务写作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">M</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mclose">)</span></span></span></span>。prompt 拆成显式目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 与隐式约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>，一段合法视频必须满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 且在<strong>所有帧</strong>上遵守 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>。</p><p>按采样率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 均匀抽帧得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1244em;vertical-align:-0.2831em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span></span></span></span>，用 VLM judge <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.1847em;">J</span></span></span></span> 判定：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">POC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1968em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.1847em;">J</span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">OC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∧</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">PC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span></span></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">OC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord">∃</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1412em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">t</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">PC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord">∀</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1412em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="delimsizing size1">]</span></span></span></span></span></span></p><p>这里最值得停下来看的是两个量词的不对称。OC 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">∃</span></span></span></span>，因为模型可能在任意时刻达成目标，之后还可能继续生成无关内容；PC 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">∀</span></span></span></span>，因为约束是持续有效的。取合取意味着：<strong>任何一帧的违规都会让整段视频归零</strong>。</p><p>这个设计有一个直接的数学后果，论文自己的消融也印证了：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">PC@</span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 单调不增。设单帧被判违规的概率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span>（含 judge 的假阳性），若各帧近似独立，则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">Pr</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">PC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span></span></span></span></span></span></span>，随采样密度指数衰减。表 4 里 Veo 3.1 的 PC 从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span> 的 33.7 降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.0</span></span></span></span> 的 21.8 再到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.0</span></span></span></span> 的 16.5，而同期 OC 只在 61.5/59.7/58.9 之间微动——这正是全称量词的形状。这一点在 §11 里会成为主要攻击面。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>outcome-hacking 真的存在吗？</strong> 50 例诊断集上，Veo 3.1 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">last</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 66.0 对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">process</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 30.0，hacking rate 36.0；Sora 2 是 70.0 对 24.0，hacking rate 46.0。只看末帧会让人以为这两个模型有不错的推理能力，看整段就掉到 30% 以下。</p><p><strong>全量评测结果如何？</strong> POC@1.0 全线低于 30%：Sora 2 最高 23.3，Veo 3.1 20.3，Wan 2.6 18.6，Seedance 1.5 9.5，Hunyuan 1.5 8.1，Wan 2.2 7.7。hacking rate 上 Veo 3.1 最严重（35.8），Seedance 1.5 次之（31.6），Wan 2.2 27.9，Wan 2.6 24.0，Sora 2 23.7，Hunyuan 1.5 19.4。</p><p>领域间差异很大且有结构。符号推理是多数模型的死穴（Wan 2.2、Hunyuan 1.5、Seedance 1.5 全部为 0.0），因为写不出清晰可读的文字；Sora 2 在这一项上拿到 58.3，是它总分第一的主要来源。反过来，在与真实世界更接近的规划与物理上，Veo 3.1（41.0 / 14.7）明显强于 Sora 2（15.1 / 9.4）。也就是说，两个头部模型的「推理能力」是沿不同轴发展的，用单一总分排名会掩盖这一点。</p><p><strong>test-time scaling 有用吗？</strong> 采多条视频算 Pass@<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>（判据仍是 POC@1.0）：Veo 3.1 从 20.3 涨到 Pass@4 的 34.3、Pass@8 的 43.2；Sora 2 从 23.3 涨到 46.1、58.6。增益显著但随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 饱和，且空间与物理两个领域始终是短板。结论是采样扩展能缓解不能治本。</p><p><strong>采样率怎么选？</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 越大判据越严，POC 单调下降（见 §6）。作者取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.0</span></span></span></span> 作为严格性与开销的折中。</p><p><strong>judge 可靠吗？</strong> 用三层 rubric 后与人类专家一致率超过 90%，不用 rubric 只有约 60%。</p><p><strong>失败模式是什么？</strong> 论文归纳了四类：<strong>约束违反</strong>（识别不出隐式规则，穿墙、走非法棋步）；<strong>停不下来</strong>（视频时长固定，任务完成后继续生成，引入多余运动与幻觉）；<strong>编辑泄漏</strong>（改动了不该改的区域，背景变化、凭空多出物体）；<strong>文字乱码</strong>（符号推理里生成不可读的字形，即使结论对也无法构成可解释的推理过程）。</p><p><strong>约束违反是能力问题还是理解问题？</strong> 作者把过程约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 显式补进输入再测 Veo 3.1：总分从 20.3 升到 22.7，结构推理从 20.0 升到 31.3。这个结果的解读很关键——失败往往不是画不出来，而是没意识到有这条规则。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：现有 GVR 评测只看末帧或最佳帧，会把「过程错但结论对」的视频判为成功。诊断实验显示 Veo 3.1 与 Sora 2 的 hacking rate 高达 36% 与 46%。VIPER 用 16 个任务、6 个领域、309 条样本，配合 POC@<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 指标——存在一帧达成目标 且 所有采样帧遵守隐式约束——把过程纳入判据。全部模型 POC@1.0 低于 30%，最高的 Sora 2 只有 23.3。test-time scaling 能把 Sora 2 推到 Pass@8 的 58.6，但空间与物理推理始终是瓶颈；把隐式约束显式写进 prompt 也能涨点，说明相当一部分失败源于不理解规则而非画不出来。</p><p><strong>3 句话版</strong>：把 prompt 拆成显式目标（存在量词）与隐式约束（全称量词），评测才能同时覆盖结论与过程。当前视频模型远达不到通用视觉推理器，且不同模型的强项分布在完全不同的领域上。VLM-as-Judge 必须配层次化 rubric，否则与人的一致率只有 60%。</p><p><strong>1 句话版</strong>：推理的正确性住在全称量词里，只看末帧等于只验证了存在量词。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>「VLM judge 的逐帧判断足够可靠，以至于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">∀</span></span></span></span> 合取不会被假阳性淹没。」</p><p>这是整个指标的承重墙。PC@<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个逐帧判断的合取，任何一次假阳性（把合规帧误判为违规）都会让整段视频归零。作者报告的一致率是 90% 以上——但那是<strong>单次判定</strong>的一致率，而 PC 要求连续 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 次都不出错。若单帧误判率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span> 且近似独立，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 时 PC 的假阴性率就高达 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">0.</span><span class="mord"><span class="mord">9</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">8</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">57%</span></span></span></span>。这个数量级与论文报告的 POC 绝对值（都在 20% 上下）相当，意味着分数里有多大比例是模型的错、多大比例是 judge 的错，无法从现有数据分辨。</p><p>论文提供的证据只有一条 90% 的一致率曲线（图 4），既没有给出误判在 OC 与 PC 上的分解，也没有给出<strong>真值视频</strong>在 POC 下的得分。后者是最直接的上界校准：VIPER 的部分任务是有真值视频的（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 定义里明说「有真值视频就从中采样」），把真值视频送进同一套 judge，如果它拿不到接近 100 的 POC，那么 23.3 这个数字的解释力就大打折扣。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，全部围绕给 POC 定标：</p><ul><li><strong>上界校准</strong>：取 VIPER 里所有带真值视频的任务，把真值视频当作模型输出送进同一套 judge，报告 POC@0.5 / 1.0 / 2.0。这个数就是指标的天花板。</li><li><strong>judge 方差</strong>：对同一段视频、同一 rubric，重复调用 judge 5 次，统计 PC 与 OC 各自的翻转率。这直接给出 §9 里那个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span> 的估计。</li><li><strong>量词分离</strong>：把 PC 的判据从「所有帧都合规」放宽成「至少 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 比例的帧合规」，扫 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.2</span><span class="mclose">}</span></span></span></span>，看模型排名是否稳定。</li></ul><p>支持论文的结果：真值视频的 POC 在 90 以上，judge 翻转率低于 5%，且放宽 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 后模型排名不变——那么 POC 的绝对值可信，模型确实只有 20% 出头。反驳的结果：真值视频只能拿 50–60，或者 judge 翻转率超过 15%，那么 POC 更适合当相对排序工具，绝对值不可解释，「low than 30%」这个 headline 需要重述。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释</strong>：POC 随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 下降这一现象，作者解释为「采样越密判据越严」，但存在一个纯统计的替代解释——多重比较。表 4 的数字恰好支持这个解释：Veo 3.1 的 OC 在三个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 下几乎不动（61.5 / 59.7 / 58.9），而 PC 单调塌陷（33.7 / 21.8 / 16.5）。如果模型的过程质量是固定的，PC 本不该随观测密度变化；它变化，说明变化的是<strong>被抓到的机会</strong>，而不是被评的对象。用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">Pr</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">PC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span></span></span></span></span></span></span> 拟合这三个点，可以反解出隐含的单帧违规率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span>，再与 judge 的自洽性对照——若两者数量级相当，PC 就更像在测「judge 有多爱找茬」而非「模型有多守规矩」。</p><p>这个攻击有一个干净的实验形式：固定采样帧数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>（而非采样率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>），改变视频长度。如果 POC 在固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 下对视频长度不敏感，说明作者的解释成立；如果 POC 主要随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 变化而与内容长度无关，那 PC 的分数就是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 的函数，跨模型比较只在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 相同时才有意义——而不同模型的默认输出时长本来就不同（Sora 2 与 Wan 2.2 的默认时长不一致），这会在排名里引入系统性偏差。</p><p><strong>第二个攻击点</strong>：表 5 显示把隐式约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 显式补进输入后 Veo 3.1 涨了 2.4 个点，作者据此断言「失败源于不理解指令而非生成能力不足」。但 judge 用的正是同一份 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>。把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 同时给模型和 judge，等于让二者在同一份措辞上对齐，涨点可能来自措辞对齐而非真实理解。要排除它，需要让 judge 用一份<strong>改写过、语义等价但表述不同</strong>的约束，看增益是否保留。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：POC 是一个二值的、事后的合取判据。它能告诉你这段视频不合格，不能告诉你它在<strong>第几帧</strong>开始偏离、偏离了多远、以及这次偏离是否可恢复。而 §11 论证了二值合取本身对 judge 噪声和采样密度极度敏感——这两个问题有同一个根源：把一条轨迹压成了一个比特。</p><p><strong>新 framing</strong>：不要问「这段推理对不对」，要问「这段推理在什么时候、以多快的速度离开了合法状态空间」。把 GVR 评测从分类问题改写成<strong>首次偏离时刻与偏离幅度的估计问题</strong>，即为每段视频输出一条「合法性随时间的衰减曲线」而不是一个 0/1。这样做有三个直接好处：judge 的单帧噪声被曲线平滑掉而不是被合取放大；采样密度只影响曲线分辨率、不影响期望值；而且它给出了训练信号——首次偏离时刻正是 process reward model 需要的监督位置。</p><p><strong>可借鉴的邻域工具</strong>：语言推理里的 process reward model 已经把「逐步打分而非结果打分」做成了标准配方，并证明它比 outcome reward 更能支撑 search 与 RL；生存分析里的 hazard function 恰好是「首次事件发生时刻」的成熟统计框架，可以直接借来定义合法性衰减率并处理右删失（视频没跑完就结束的情况）。</p><p><strong>第一个实验</strong>：只取迷宫这一个任务，因为它的约束（不穿墙）可以用纯几何方法<strong>程序化</strong>判定，不需要 VLM。对每段生成视频逐帧计算路径与墙体的重叠像素数，得到一条连续的违规曲线。先做两件事：一是把这条程序化曲线与 GPT-5 judge 的逐帧判定对照，量化 judge 的假阳性率；二是比较「首次偏离时刻」与二值 POC 在区分模型上的信噪比。若前者的方差显著更小，就为整套指标的连续化提供了直接依据。</p>',58)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
